package com.rwi.myrepublic.astri.internal;import com.rwi.myrepublic.astri.AstriConfig;import java.io.IOException;import java.net.URI;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;import java.time.Duration;import java.util.Base64;public class PriceListClient{private HttpClient client;private AstriConfig config;private String authHeader;public
PriceListClient(){this.config=AstriConfig.getInstance();this.client=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(config.getConnectionTimeout())).build();String credentials=config.getUsername()+ ":"+config.getPassword();this.authHeader= "Basic "+Base64.getEncoder().encodeToString(credentials.getBytes());}public String getPriceList(String filterParams)throws IOException,InterruptedException{String baseUrl=config.getApiBaseUrl();String path= "/device/price/list/all";String
url=baseUrl+path;if(filterParams!=null&&!filterParams.isEmpty()){url+= "?"+filterParams;}HttpRequest request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization",authHeader).timeout(Duration.ofMillis(config.getRequestTimeout())).GET().build();HttpResponse<String>response=client.send(request,HttpResponse.BodyHandlers.ofString());return response.body();}public void close(){}}